import {solve} from './physics.js';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const state={mode:'single',mass:100,a:20,b:20,middle:50,forces:true};
const fmt=x=>Number.isInteger(x)?String(x):x.toFixed(1);
const colors={a:'#198373',b:'#d28a4a'};
let toastTimer;
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),2300);}
function spring(x,y,len,c,label){let d=`M ${x} ${y} v 10`;const coils=9,available=Math.max(8,len-20);for(let n=0;n<coils*2;n++){d+=` L ${x+(n%2===0?-13:13)} ${y+10+available*(n+.5)/(coils*2)}`;}d+=` L ${x} ${y+len-10} v 10`;return `<path d="${d}" fill="none" stroke="${c}" stroke-width="3.3" stroke-linejoin="round" stroke-linecap="round"/><rect x="${x-47}" y="${y+len/2-12}" width="25" height="25" rx="7" fill="${c}" opacity=".12"/><text x="${x-34.5}" y="${y+len/2+5}" text-anchor="middle" fill="${c}" font-size="13" font-weight="700">${label}</text>`;}
function bracket(x,y1,y2,c,label){if(Math.abs(y2-y1)<.2)return '';return `<path d="M${x-5} ${y1}h10M${x} ${y1}V${y2}M${x-5} ${y2}h10" stroke="${c}" stroke-width="1.6" fill="none"/><rect x="${x+8}" y="${(y1+y2)/2-12}" width="91" height="24" rx="5" fill="#fafbf8" opacity=".96"/><text x="${x+13}" y="${(y1+y2)/2+4}" fill="${c}" font-size="12" font-weight="600">${label}</text>`;}
function naturalGuide(x,y,width){return `<line x1="${x}" y1="${y}" x2="${x+width}" y2="${y}" stroke="#a2b5a5" stroke-dasharray="5 5" stroke-width="1.3"/>`;}
function weight(x,y,m,small=false){const w=small?65:98,h=small?35:47;return `<path d="M${x-7} ${y+7}v-4a7 7 0 0 1 14 0v4" stroke="#8d9e91" stroke-width="2" fill="none"/><path d="M${x-w/2+6} ${y+8}h${w-12}l6 ${h-8}h-${w}z" fill="${small?'#f0dfc6':'#dce7dc'}" stroke="${small?'#d4b990':'#b7cbb9'}" stroke-width="1.5"/><text x="${x}" y="${y+h/2+12}" text-anchor="middle" fill="#506d58" font-size="${small?13:18}" font-weight="700">${fmt(m)}<tspan font-size="11" font-weight="400"> g</tspan></text>`;}
function arrow(x,y,value,c,label){if(!state.forces||value===0)return '';const len=30+Math.min(48,value/4);return `<line x1="${x}" y1="${y}" x2="${x}" y2="${y-len}" stroke="${c}" stroke-width="2.4" marker-end="url(#arrow-${c===colors.a?'a':'b'})"/><text x="${x+10}" y="${y-len/2+4}" fill="${c}" font-size="11">${label} ${fmt(value)} g分</text>`;}
function renderScene(r){const dual=state.mode==='series'||state.mode==='advanced',parallel=state.mode==='parallel';const scale=Math.min(15,310/r.total),top=56,base=top+r.total*scale;let s=`<defs><pattern id="hatch" width="8" height="8" patternUnits="userSpaceOnUse"><path d="M-2 8L8-2M6 10l4-4" stroke="#c0cdbf" stroke-width="1.3"/></pattern><marker id="arrow-a" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="5" markerHeight="5" orient="auto-start-reverse"><path d="M0 0L10 5L0 10z" fill="${colors.a}"/></marker><marker id="arrow-b" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="5" markerHeight="5" orient="auto-start-reverse"><path d="M0 0L10 5L0 10z" fill="${colors.b}"/></marker></defs>`;
// Fixed support and a centimetre ruler share the same physical coordinate scale.
s+=`<rect x="207" y="37" width="296" height="17" fill="url(#hatch)"/><path d="M207 55H503" stroke="#8ca38f" stroke-width="3" stroke-linecap="round"/><text x="149" y="32" fill="#8b9d8d" font-size="10">目盛り / cm</text>`;
let maxCm=Math.ceil((r.total+2)/5)*5,step=scale<9?5:2;
for(let cm=0;cm<=maxCm;cm++){const y=top+cm*scale;if(y>435)break;const major=cm%step===0;s+=`<path d="M${major?170:176} ${y}h${major?16:10}" stroke="#b6c7b7" stroke-width="${major?1.2:.8}"/>`;if(major)s+=`<text x="158" y="${y+4}" text-anchor="end" fill="#92a491" font-size="11">${cm}</text>`;}
s+=`<path d="M186 ${top}V${Math.min(435,top+maxCm*scale)}" stroke="#b6c7b7"/>`;
if(parallel){const xa=292,xb=418;s+=naturalGuide(258,top+8*scale,248);s+=spring(xa,top,(8+r.xA)*scale,colors.a,'A')+spring(xb,top,(8+r.xB)*scale,colors.b,'B');s+=`<path d="M${xa-15} ${base}H${xb+15}" stroke="#829d88" stroke-width="6" stroke-linecap="round"/><path d="M355 ${base}v15" stroke="#829d88" stroke-width="2"/>`+weight(355,base+17,state.mass);s+=bracket(485,top+8*scale,base,colors.a,`のび ${fmt(r.xA)} cm`);s+=arrow(268,base-7,r.loadA,colors.a,'A')+arrow(444,base-7,r.loadB,colors.b,'B');
}else if(dual){const x=350,joint=top+(8+r.xA)*scale;s+=naturalGuide(x+16,top+8*scale,100)+naturalGuide(x+16,joint+8*scale,100);s+=spring(x,top,(8+r.xA)*scale,colors.a,'A')+spring(x,joint,(8+r.xB)*scale,colors.b,'B');s+=`<circle cx="${x}" cy="${joint}" r="4" fill="#6f8e78"/>`;s+=bracket(430,top+8*scale,joint,colors.a,`のび ${fmt(r.xA)} cm`)+bracket(430,joint+8*scale,base,colors.b,`のび ${fmt(r.xB)} cm`);s+=weight(x,base+3,state.mass);s+=arrow(275,joint-5,r.loadA,colors.a,'A')+arrow(275,base-5,r.loadB,colors.b,'B');if(state.mode==='advanced'){s+=`<path d="M${x+3} ${joint}H${x+65}v4" stroke="#ad9673" stroke-width="1.6" fill="none"/>`+weight(x+85,joint+3,state.middle,true);}
}else{const x=350;s+=naturalGuide(x-15,top+8*scale,172);s+=spring(x,top,(8+r.xA)*scale,colors.a,'A');s+=bracket(465,top+8*scale,base,colors.a,`のび ${fmt(r.xA)} cm`);s+=weight(x,base+3,state.mass)+arrow(285,base-5,r.loadA,colors.a,'A');s+=`<text x="513" y="${top+8*scale-8}" fill="#8fa18e" font-size="10">自然長 8 cm の位置</text>`;}
s+=`<text x="355" y="${Math.min(459,base+82)}" text-anchor="middle" fill="#8a9a8b" font-size="10">${state.mass===0?'おもりを追加してみよう':'止まったときの、つり合いのようす'}</text>`;$('#scene').innerHTML=s;$('#zoom-label').textContent=scale<14.9?'図は全体が見える縮尺で表示':'';}
function renderGraph(r){const W=570,H=220,left=54,right=535,top=26,bottom=177;const end=solve({...state,mass:300});const ymax=Math.max(10,Math.ceil(end.extension/5)*5);const px=m=>left+m/300*(right-left),py=x=>bottom-x/ymax*(bottom-top);let s=`<text x="${left}" y="13" fill="#8b9c8e" font-size="10">ばね全体ののび（cm）</text>`;for(let i=0;i<=4;i++){const val=ymax*i/4,y=py(val);s+=`<path d="M${left} ${y}H${right}" stroke="#e9eee7"/><text x="${left-10}" y="${y+3}" text-anchor="end" fill="#9aa69a" font-size="10">${fmt(val)}</text>`;}for(let m=0;m<=300;m+=50){s+=`<path d="M${px(m)} ${top}V${bottom}" stroke="#f0f3ed"/><text x="${px(m)}" y="${bottom+18}" text-anchor="middle" fill="#9aa69a" font-size="10">${m}</text>`;}const start=solve({...state,mass:0}).extension;s+=`<path d="M${px(0)} ${py(start)}L${px(300)} ${py(end.extension)}" stroke="#b1d2ba" stroke-width="2"/>`;s+=`<path d="M${left} ${py(r.extension)}H${px(state.mass)}V${bottom}" stroke="#83b79a" stroke-dasharray="4 4" fill="none"/><circle cx="${px(state.mass)}" cy="${py(r.extension)}" r="9" fill="#198373" opacity=".12"/><circle cx="${px(state.mass)}" cy="${py(r.extension)}" r="4.5" fill="#198373" stroke="white" stroke-width="1.5"/><text x="${state.mass>230?px(state.mass)-12:px(state.mass)+12}" y="${Math.max(20,py(r.extension)-11)}" text-anchor="${state.mass>230?'end':'start'}" fill="#198373" font-size="11" font-weight="600">${fmt(r.extension)} cm</text><text x="${right}" y="215" text-anchor="end" fill="#8b9c8e" font-size="10">下のおもりの重さ（g）</text>`;$('#graph').innerHTML=s;$('#graph-explain').textContent=state.mode==='advanced'?'接続点のおもりを固定して比較。0 gでも上のばねはのびるよ。':'自然長を除いた「のび」をグラフにしています。';}
function row(label,load,extension,c){return `<div class="result-row"><div class="result-title"><span class="spring-badge ${c}">${label}</span>ばね ${label}<small>自然長 8 cm</small></div><div class="result-values"><div>支える重さ<strong>${fmt(load)}<small>g分</small></strong></div><div>のび<strong>${fmt(extension)}<small>cm</small></strong></div></div></div>`;}
function render(){const r=solve(state);$$('[data-mode]').forEach(b=>{const active=b.dataset.mode===state.mode;b.classList.toggle('active',active);b.setAttribute('aria-pressed',active);});$('#mass').value=state.mass;$('#middle').value=state.middle;$('#stiff-a').value=state.a;$('#stiff-b').value=state.b;$('#show-forces').checked=state.forces;$('#mass-value').innerHTML=`${state.mass} <small>g</small>`;$('#middle-value').innerHTML=`${state.middle} <small>g</small>`;$('#middle-control').hidden=state.mode!=='advanced';$('#setting-b').hidden=!r.two;$('#spring-results').innerHTML=row('A',r.loadA,r.xA,'a')+(r.two?row('B',r.loadB,r.xB,'b'):'');$('#total-value').innerHTML=`${r.total.toFixed(1)}<span>cm</span>`;$('#mode-caption').textContent={single:'1本のばねに、おもりをつるす',series:'ばねをたてにつなぐと、どうなる？',parallel:'2本のばねで、ひとつのおもりを支える',advanced:'接続点にも、おもりをつけてみよう'}[state.mode];let insight={single:`${state.a} gのおもりで1 cmのびるばね。<b>「全長 − 自然長」が、のび</b>だよ。いまは ${fmt(r.total)} − 8 ＝ ${fmt(r.xA)} cm。`,series:`直列では、どちらのばねも<b>同じ ${state.mass} g分の力</b>で引かれるよ。全体ののびは ${fmt(r.xA)} ＋ ${fmt(r.xB)} ＝ ${fmt(r.extension)} cm。`,parallel:`並列では、2本でおもりを支えるよ。<b>のびは同じ</b>で、支える重さは A が ${fmt(r.loadA)} g分、B が ${fmt(r.loadB)} g分。`,advanced:`上のAは<b>接続点と下のおもりの両方</b>を支えるよ。A は ${state.middle} ＋ ${state.mass} ＝ ${fmt(r.loadA)} g分、B は ${state.mass} g分。`};$('#insight').innerHTML=insight[state.mode];renderScene(r);renderGraph(r);}
$$('[data-mode]').forEach(b=>b.addEventListener('click',()=>{state.mode=b.dataset.mode;render();}));
$('#mass').addEventListener('input',e=>{state.mass=+e.target.value;render();});$('#middle').addEventListener('input',e=>{state.middle=+e.target.value;render();});$('#stiff-a').addEventListener('change',e=>{state.a=+e.target.value;render();});$('#stiff-b').addEventListener('change',e=>{state.b=+e.target.value;render();});$('#show-forces').addEventListener('change',e=>{state.forces=e.target.checked;render();});$('#clear-mass').addEventListener('click',()=>{state.mass=0;render();toast('下のおもりを外しました');});
function addMass(v){if(state.mass+v>300){toast('下のおもりは300 gまで追加できます');return;}state.mass+=v;render();toast(`${v} gのおもりを追加しました`);}
// A single pointer gesture supports touch, pen, mouse and keyboard button activation.
$$('[data-weight]').forEach(button=>{let drag=null,suppress=false;button.addEventListener('pointerdown',e=>{if(e.button!==0)return;drag={x:e.clientX,y:e.clientY,moving:false};button.setPointerCapture(e.pointerId);});button.addEventListener('pointermove',e=>{if(!drag)return;if(Math.hypot(e.clientX-drag.x,e.clientY-drag.y)>7)drag.moving=true;if(!drag.moving)return;let ghost=$('.drag-ghost');if(!ghost){ghost=document.createElement('div');ghost.className='drag-ghost';ghost.textContent=`+ ${button.dataset.weight} g`;document.body.append(ghost);}ghost.style.left=`${e.clientX}px`;ghost.style.top=`${e.clientY}px`;const rect=$('#dropzone').getBoundingClientRect();$('#dropzone').classList.toggle('drop-hover',e.clientX>=rect.left&&e.clientX<=rect.right&&e.clientY>=rect.top&&e.clientY<=rect.bottom);});const cleanup=()=>{$('.drag-ghost')?.remove();$('#dropzone').classList.remove('drop-hover');drag=null;};button.addEventListener('pointerup',e=>{if(drag?.moving){suppress=true;const rect=$('#dropzone').getBoundingClientRect();if(e.clientX>=rect.left&&e.clientX<=rect.right&&e.clientY>=rect.top&&e.clientY<=rect.bottom)addMass(+button.dataset.weight);setTimeout(()=>suppress=false,0);}cleanup();});button.addEventListener('pointercancel',cleanup);button.addEventListener('click',()=>{if(!suppress)addMass(+button.dataset.weight);});});
const quizzes=[{question:'20 gで1 cmのびるばね。100 gのおもりをつるすと、「のび」は何cm？',choices:['5 cm','8 cm','13 cm'],answer:0,explain:'正解！100 ÷ 20 ＝ 5 cm。自然長8 cmを足した13 cmは「全長」だね。',setup:{mode:'single',mass:100,a:20,b:20,middle:50}},{question:'同じばね2本を直列に。1本で5 cmのびるおもりをつるすと、全体の「のび」は？',choices:['2.5 cm','5 cm','10 cm'],answer:2,explain:'正解！どちらにも同じ力がかかり、5 ＋ 5 ＝ 10 cmのびるよ。',setup:{mode:'series',mass:100,a:20,b:20,middle:50}},{question:'20 gで1 cmのびる同じばね2本を並列に。100 gのおもりを支えると、それぞれの「のび」は？',choices:['2.5 cm','5 cm','10 cm'],answer:0,explain:'正解！同じばねなので50 g分ずつ支えるよ。50 ÷ 20 ＝ 2.5 cm。',setup:{mode:'parallel',mass:100,a:20,b:20,middle:50}},{question:'直列の接続点に50 g、いちばん下に100 g。上のばねAが支える重さは何g分？',choices:['50 g分','100 g分','150 g分'],answer:2,explain:'正解！上のAは、接続点の50 gと下の100 gを両方支えるよ。',setup:{mode:'advanced',mass:100,a:20,b:20,middle:50}}];let quizIndex=0;
function renderQuiz(){const q=quizzes[quizIndex];$('#quiz-count').textContent=`${quizIndex+1} / ${quizzes.length}`;$('#quiz-question').textContent=q.question;$('#quiz-feedback').textContent='答えを選んでから、実験台でも試してみよう。';$('#quiz-feedback').classList.remove('success');$('#quiz-choices').innerHTML=q.choices.map((c,i)=>`<button data-choice="${i}">${c}</button>`).join('');$$('[data-choice]').forEach(btn=>btn.addEventListener('click',()=>{const correct=+btn.dataset.choice===q.answer;$$('[data-choice]').forEach(b=>{b.classList.remove('correct','wrong');b.setAttribute('aria-pressed',String(b===btn));});btn.classList.add(correct?'correct':'wrong');$('#quiz-feedback').textContent=correct?q.explain:'もう一度考えてみよう。「この条件で実験する」で、各ばねの力とのびを確かめられるよ。';$('#quiz-feedback').classList.toggle('success',correct);}));}
$('#next-quiz').addEventListener('click',()=>{quizIndex=(quizIndex+1)%quizzes.length;renderQuiz();});$('#quiz-setup').addEventListener('click',()=>{Object.assign(state,quizzes[quizIndex].setup);render();$('#experiment-title').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'});toast('問題の条件を実験台にセットしました');});$('#reset').addEventListener('click',()=>{Object.assign(state,{mode:'single',mass:100,a:20,b:20,middle:50,forces:true});quizIndex=0;render();renderQuiz();toast('最初の状態に戻しました');});
render();renderQuiz();
